            if !agents.is_empty() {
                lines.push(truncate_to_width(
                    &format!(
                        "    {label}: {}",
                        agents
                            .iter()
                            .map(AgentId::as_str)
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                    width,
                ));
            }
        }
    }
    lines
}

