fn agent_list_labels(agent: &AgentListEntry) -> (&str, &str) {
    if agent.id.as_str().starts_with("review-") {
        (agent.id.as_str(), &agent.feature)
    } else {
        (&agent.feature, agent.id.as_str())
    }
}

fn compact_agent_row(agent: &AgentListEntry, selected: bool, width: usize) -> String {
    let prefix = if selected { ">" } else { " " };
    let status = if agent.ready { " READY" } else { "" };
    let id = agent.id.as_str();
    let width = width.max(1);

    let row = if id.starts_with("review-") {
        compact_fixed_first(prefix, id, &agent.feature, status, width)
    } else {
        compact_fixed_last(prefix, &agent.feature, id, status, width)
    };
    truncate_to_width(&row, width)
}

fn compact_fixed_first(
    prefix: &str,
    fixed: &str,
    flexible: &str,
    status: &str,
    width: usize,
) -> String {
    let fixed_width = prefix.chars().count() + fixed.chars().count() + status.chars().count();
    if fixed_width >= width {
        return format!("{prefix}{fixed}{status}");
    }

    let flexible_width = width.saturating_sub(fixed_width + 1);
    format!(
        "{prefix}{fixed} {}{status}",
        truncate_to_width(flexible, flexible_width)
    )
}

fn compact_fixed_last(
    prefix: &str,
    flexible: &str,
    fixed: &str,
    status: &str,
    width: usize,
) -> String {
    let fixed_width = prefix.chars().count() + 1 + fixed.chars().count() + status.chars().count();
    if fixed_width >= width {
        return format!("{prefix}{fixed}{status}");
    }

    let flexible_width = width.saturating_sub(fixed_width);
    format!(
        "{prefix}{} {fixed}{status}",
        truncate_to_width(flexible, flexible_width)
    )
}

fn truncate_to_width(text: &str, width: usize) -> String {
    text.chars().take(width).collect()
}

fn wrapped_display_lines(content: &str, width: u16) -> Vec<String> {
    content
        .split('\n')
        .flat_map(|line| wrap_display_line(line, width))
        .collect()
}

fn wrap_display_line(line: &str, width: u16) -> Vec<String> {
    let width = usize::from(width.max(1));
    if line.is_empty() {
        return vec![String::new()];
    }
    let chars = line.chars().collect::<Vec<_>>();
    chars
        .chunks(width)
        .map(|chunk| chunk.iter().collect::<String>())
        .collect()
}

fn selected_ranges(
    selection: &VisualSelection,
    lines: &[String],
) -> Vec<(usize, usize, usize)> {
    let Some(last_row) = lines.len().checked_sub(1) else {
        return Vec::new();
    };
    let anchor = SelectionPoint {
        row: selection.anchor.row.min(last_row),
        column: selection.anchor.column,
    };
    let cursor = SelectionPoint {
        row: selection.cursor.row.min(last_row),
        column: selection.cursor.column,
    };

    match selection.kind {
        VisualSelectionKind::Line => {
            let (start_row, end_row) = ordered_rows(anchor.row, cursor.row);
            (start_row..=end_row)
                .map(|row| (row, 0, char_len(&lines[row])))

                .map(|row| (row, 0, char_len(&lines[row])))
                .collect()
        }
        VisualSelectionKind::Block => {
            let (start_row, end_row) = ordered_rows(anchor.row, cursor.row);
            let (start_column, end_column) = ordered_rows(anchor.column, cursor.column);
            (start_row..=end_row)
                .map(|row| {
                    let len = char_len(&lines[row]);
                    let start = start_column.min(len);
                    let end = end_column.saturating_add(1).min(len);
                    (row, start, end.max(start))
                })
                .collect()
        }
        VisualSelectionKind::Character => character_selection_ranges(anchor, cursor, lines),
    }
}

fn character_selection_ranges(
    anchor: SelectionPoint,
    cursor: SelectionPoint,
    lines: &[String],
) -> Vec<(usize, usize, usize)> {
    let (start, end) = if point_le(anchor, cursor) {
        (anchor, cursor)
    } else {
        (cursor, anchor)
    };
    (start.row..=end.row)
        .map(|row| {
            let len = char_len(&lines[row]);
            if len == 0 {
                return (row, 0, 0);
            }
            if start.row == end.row {
                let start_column = start.column.min(len - 1);
                let end_column = end.column.min(len - 1).saturating_add(1);
                return (row, start_column, end_column.max(start_column));
            }
            if row == start.row {
                let start_column = start.column.min(len - 1);
                return (row, start_column, len);
            }
            if row == end.row {
                let end_column = end.column.min(len - 1).saturating_add(1);
                return (row, 0, end_column);
            }
            (row, 0, len)
        })
        .collect()
}

fn point_le(left: SelectionPoint, right: SelectionPoint) -> bool {
    left.row < right.row || (left.row == right.row && left.column <= right.column)
}

fn ordered_rows(left: usize, right: usize) -> (usize, usize) {
    if left <= right {
        (left, right)
    } else {
        (right, left)
    }
}

fn char_len(line: &str) -> usize {
    line.chars().count()
}

fn char_range(line: &str, start: usize, end: usize) -> String {
    line.chars()
        .skip(start)
        .take(end.saturating_sub(start))
        .collect()
}

fn base64_encode(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut encoded = String::new();
    for chunk in bytes.chunks(3) {
        let first = chunk[0];
        let second = chunk.get(1).copied().unwrap_or(0);
        let third = chunk.get(2).copied().unwrap_or(0);
        let triple = ((first as u32) << 16) | ((second as u32) << 8) | third as u32;
        encoded.push(TABLE[((triple >> 18) & 0x3f) as usize] as char);
        encoded.push(TABLE[((triple >> 12) & 0x3f) as usize] as char);
        encoded.push(if chunk.len() > 1 {
            TABLE[((triple >> 6) & 0x3f) as usize] as char
        } else {
            '='
        });
        encoded.push(if chunk.len() > 2 {
            TABLE[(triple & 0x3f) as usize] as char
        } else {
            '='
        });
    }
    encoded
}

fn buffer_to_string(buffer: &Buffer) -> String {
    const ANSI_REVERSE_VIDEO: &str = "\u{1b}[7m";
    const ANSI_RESET: &str = "\u{1b}[0m";
    let mut output = String::new();
    for y in 0..buffer.area.height {
        let mut reversed = false;
        for x in 0..buffer.area.width {
            let cell = buffer.get(x, y);
            let cell_reversed = cell.modifier.contains(Modifier::REVERSED);
            if cell_reversed != reversed {
                output.push_str(if cell_reversed {
                    ANSI_REVERSE_VIDEO
                } else {
                    ANSI_RESET
                });
                reversed = cell_reversed;
            }
            output.push_str(&cell.symbol);
        }
        if reversed {
            output.push_str(ANSI_RESET);
        }
        if y + 1 < buffer.area.height {
            output.push_str("\r\n");
        }
    }
    output
}

fn visual_rows(line: &str, width: u16) -> u16 {
    visual_row_count(line, width).min(usize::from(u16::MAX)) as u16
}

fn visual_row_count(line: &str, width: u16) -> usize {
    let width = usize::from(width.max(1));
    let len = line.chars().count().min(usize::from(u16::MAX));
    (len / width).saturating_add(1)
}

fn cursor_char_count(text: &str, cursor: usize) -> usize {
    text.char_indices()
        .take_while(|(index, _)| *index < cursor)
        .count()
}

fn visible_content(content: &str, width: u16, height: u16, scroll_rows: usize) -> String {
    let height = usize::from(height);
    let Some((history, prompt)) = split_chat_prompt(content) else {
        return tail_visible_content(content, width, height, scroll_rows);
    };

    let prompt_rows = visual_row_count(prompt, width);
    let history_height = height.saturating_sub(prompt_rows).max(1);
    let visible_history = tail_visible_content(history, width, history_height, scroll_rows);
    if visible_history.is_empty() {
        prompt.to_string()
    } else {
        format!("{visible_history}\n{prompt}")
    }
}
